package app.realme.unlink

import android.annotation.SuppressLint
import android.bluetooth.BluetoothDevice

/** Bonded-device matching and naming for realme Buds Wireless 5 ANC. */
object DeviceSupport {
    const val DISPLAY_NAME = "realme Buds Wireless 5 ANC"

    @SuppressLint("MissingPermission")
    fun isTarget(device: BluetoothDevice): Boolean {
        val name = device.name ?: return false
        return name.equals(DISPLAY_NAME, ignoreCase = true) ||
            name.contains("Buds Wireless 5", ignoreCase = true)
    }

    @SuppressLint("MissingPermission")
    fun displayName(device: BluetoothDevice): String = device.name ?: DISPLAY_NAME
}

package app.realme.unlink

/**
 * Switch features that passed live write validation on Buds Wireless 5 ANC.
 * Rejected IDs must never appear as working toggles.
 */
object SwitchCatalog {
    /** IDs accepted by reversible live writes. */
    val writableIds: Set<Int> = setOf(6, 8, 9, 17, 26, 29, 38)

    /**
     * Gaming mode is advertised under both 6 and 8. Prefer 8 (baseline was on) and
     * collapse both into one logical control so the UI never shows two identical rows.
     */
    const val GAMING_PRIMARY_ID = 8
    private val gamingIds = setOf(6, 8)

    data class LogicalSwitch(
        val id: Int,
        val label: String,
        val enabled: Boolean,
        /** Extra protocol IDs that share this control (e.g. secondary gaming id). */
        val aliases: Set<Int> = emptySet(),
    )

    fun logicalSwitches(
        statuses: List<HeadsetCapabilityDiscovery.SwitchFeatureStatus>,
    ): List<LogicalSwitch> {
        val byId = statuses.associateBy { it.featureId }
        val result = mutableListOf<LogicalSwitch>()
        val consumed = mutableSetOf<Int>()

        val gamingPresent = gamingIds.any { it in byId && it in writableIds }
        if (gamingPresent) {
            val primary = byId[GAMING_PRIMARY_ID] ?: byId[6]
            if (primary != null) {
                result += LogicalSwitch(
                    id = primary.featureId.let { if (it in gamingIds) GAMING_PRIMARY_ID else it }
                        .let { preferred ->
                            if (byId.containsKey(GAMING_PRIMARY_ID)) GAMING_PRIMARY_ID
                            else primary.featureId
                        },
                    label = "Gaming mode",
                    enabled = gamingIds.any { (byId[it]?.value ?: 0) != 0 },
                    aliases = gamingIds - (
                        if (byId.containsKey(GAMING_PRIMARY_ID)) GAMING_PRIMARY_ID
                        else primary.featureId
                        ),
                )
                consumed += gamingIds
            }
        }

        // Stable product order for the remaining proven toggles.
        val order = listOf(9, 17, 26, 29, 38)
        for (id in order) {
            if (id in consumed || id !in writableIds) continue
            val status = byId[id] ?: continue
            val label = HeadsetSemantics.switchFeatureLabel(id) ?: "Feature $id"
            result += LogicalSwitch(
                id = id,
                label = label,
                enabled = status.value != 0,
            )
            consumed += id
        }

        // Any other writable IDs that appeared (defensive).
        for (status in statuses) {
            if (status.featureId in consumed || status.featureId !in writableIds) continue
            val label = HeadsetSemantics.switchFeatureLabel(status.featureId)
                ?: "Feature ${status.featureId}"
            result += LogicalSwitch(
                id = status.featureId,
                label = label,
                enabled = status.value != 0,
            )
        }
        return result
    }
}

package app.realme.unlink

/**
 * App-side EQ curves for the device's custom slot. Frequencies and dB range must come from the
 * headset profile; suggestions only supply relative shapes that are scaled into that range.
 */
object EqSuggestions {
    data class Suggestion(
        val id: String,
        val name: String,
        /** Relative weights per band index; scaled into the profile's min/max. */
        val relative: List<Float>,
    )

    val suggestions: List<Suggestion> = listOf(
        Suggestion("flat", "Flat", listOf(0f, 0f, 0f, 0f, 0f, 0f)),
        Suggestion("bass", "Bass boost", listOf(1f, 0.55f, 0.1f, 0f, 0f, 0f)),
        Suggestion("warm", "Warm", listOf(0.45f, 0.35f, 0.1f, -0.1f, -0.15f, -0.2f)),
        Suggestion("vocal", "Vocal", listOf(-0.25f, -0.1f, 0.55f, 0.7f, 0.25f, 0f)),
        Suggestion("bright", "Bright", listOf(-0.15f, -0.05f, 0.1f, 0.35f, 0.65f, 0.75f)),
        Suggestion("treble", "Treble lift", listOf(0f, 0f, 0.1f, 0.35f, 0.7f, 1f)),
    )

    fun apply(
        profile: HeadsetCapabilityDiscovery.EqProfile,
        suggestion: Suggestion,
    ): HeadsetCapabilityDiscovery.EqProfile {
        val bandCount = profile.frequencies.size
        require(bandCount > 0) { "Profile has no bands" }
        val weights = suggestion.relative
        val scaled = List(bandCount) { index ->
            val weight = weights.getOrElse(index) { 0f }.coerceIn(-1f, 1f)
            val span = if (weight >= 0f) {
                profile.maxValue.toFloat()
            } else {
                -profile.minValue.toFloat()
            }
            val raw = weight * span
            raw.toInt().coerceIn(profile.minValue, profile.maxValue)
        }
        return profile.copy(dbValues = scaled, selected = true)
    }
}

package app.realme.unlink

/** Immutable product-facing snapshot of headset state. */
data class HeadsetSnapshot(
    val deviceName: String,
    val serviceLabel: String,
    val firmwareVersion: String?,
    val batteries: List<BatteryLevel>,
    val noise: HeadsetProtocol.NoiseControlReading?,
    val currentEqId: Int?,
    val eqProfiles: List<HeadsetCapabilityDiscovery.EqProfile>,
    val bassBands: List<HeadsetCapabilityDiscovery.BassEngineValue>,
    val switches: List<SwitchCatalog.LogicalSwitch>,
    val buttonMappings: List<HeadsetCapabilityDiscovery.KeyMapping>,
    val wear: List<HeadsetCapabilityDiscovery.WearStatus>,
    val multipoint: List<HeadsetCapabilityDiscovery.MultipointEntry>,
    val findModeActive: Boolean = false,
    val capabilities: HeadsetCapabilities,
) {
    data class BatteryLevel(
        val deviceType: Int,
        val percentage: Int,
        val charging: Boolean,
    ) {
        val role: String
            get() = when (deviceType) {
                1 -> "Left"
                2 -> "Right"
                3 -> "Case"
                else -> "Bud"
            }
    }

    val primaryBatteryPercent: Int?
        get() {
            val buds = batteries.filter { it.deviceType == 1 || it.deviceType == 2 }
            if (buds.isNotEmpty()) return buds.minOf { it.percentage }
            return batteries.firstOrNull()?.percentage
        }

    val anyCharging: Boolean
        get() = batteries.any { it.charging }

    val customEqProfile: HeadsetCapabilityDiscovery.EqProfile?
        get() = eqProfiles.firstOrNull { it.id == 4 }
            ?: eqProfiles.firstOrNull { it.name.contains("Custom", ignoreCase = true) }

    val currentEqLabel: String
        get() {
            val id = currentEqId ?: return "Unknown"
            eqProfiles.firstOrNull { it.id == id }?.name?.let { return it }
            return when (id) {
                0 -> "Default"
                else -> "Profile $id"
            }
        }
}

package app.realme.unlink

import android.annotation.SuppressLint
import android.bluetooth.BluetoothAdapter
import android.bluetooth.BluetoothManager
import android.bluetooth.BluetoothSocket
import android.content.Context
import android.util.Log
import java.io.IOException
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference

/**
 * Foreground-only headset session owner.
 *
 * Connects while the UI is active, keeps the RFCOMM socket open for seamless writes, and
 * disconnects when the UI backgrounds. Never runs as a sticky/always-on service.
 */
class HeadsetController(context: Context) {
    private val appContext = context.applicationContext
    private val executor: ExecutorService = Executors.newSingleThreadExecutor()
    private val closed = AtomicBoolean(false)
    private val foreground = AtomicBoolean(false)
    private val generation = java.util.concurrent.atomic.AtomicInteger(0)

    @Volatile
    private var session: HeadsetSession? = null

    @Volatile
    private var activeSocket: BluetoothSocket? = null

    @Volatile
    private var lastSnapshot: HeadsetSnapshot? = null

    private val listener = AtomicReference<((UiEvent) -> Unit)?>(null)

    sealed class UiEvent {
        data class State(val state: ConnectionState) : UiEvent()
        data class Message(val text: String, val isError: Boolean = false) : UiEvent()
        data class Busy(val busy: Boolean) : UiEvent()
    }

    fun setListener(onEvent: ((UiEvent) -> Unit)?) {
        listener.set(onEvent)
    }

    fun onForeground() {
        if (closed.get()) return
        foreground.set(true)
        val gen = generation.incrementAndGet()
        executor.execute {
            if (!foreground.get() || gen != generation.get()) return@execute
            connectAndRefreshLocked(gen)
        }
    }

    fun onBackground() {
        foreground.set(false)
        generation.incrementAndGet()
        executor.execute {
            disconnectLocked()
            // Keep last snapshot in memory for a warm-looking resume; state becomes Connecting
            // again on next foreground.
        }
    }

    fun refresh() {
        if (!foreground.get()) return
        val gen = generation.get()
        executor.execute {
            if (!foreground.get() || gen != generation.get()) return@execute
            try {
                emitBusy(true)
                val current = session
                if (current == null) {
                    connectAndRefreshLocked(gen)
                } else {
                    val snapshot = readSnapshot(current)
                    lastSnapshot = snapshot
                    emitState(ConnectionState.Connected(snapshot))
                }
            } catch (error: Exception) {
                handleSessionFailure(error, gen)
            } finally {
                emitBusy(false)
            }
        }
    }

    fun setNoiseValue(value: Int) {
        mutate("noise control") { session, snap ->
            val baseline = snap.noise
                ?: error("Noise control is not available")
            val next = baseline.copy(value = value)
            checkWrite(session.setNoiseControl(next))
            next
        }
    }

    fun setEqId(eqId: Int) {
        mutate("EQ profile") { session, _ ->
            checkWrite(session.setEqStatus(eqId))
            eqId
        }
    }

    fun applyCustomEq(profile: HeadsetCapabilityDiscovery.EqProfile) {
        mutate("custom EQ") { session, _ ->
            checkWrite(session.setCustomEq(action = 2, profile = profile))
            checkWrite(session.setEqStatus(profile.id))
            profile
        }
    }

    fun setBassBand(band: HeadsetCapabilityDiscovery.BassEngineValue) {
        mutate("bass") { session, _ ->
            checkWrite(session.setBassEngine(band))
            band
        }
    }

    fun setSwitch(id: Int, enabled: Boolean) {
        mutate("switch $id") { session, snap ->
            val logical = snap.switches.firstOrNull { it.id == id || id in it.aliases }
            checkWrite(session.setSwitchFeature(id, enabled))
            // If gaming has aliases, keep the secondary id in sync best-effort.
            logical?.aliases?.forEach { alias ->
                runCatching { checkWrite(session.setSwitchFeature(alias, enabled)) }
            }
            enabled
        }
    }

    fun setButtonMappings(mappings: List<HeadsetCapabilityDiscovery.KeyMapping>) {
        mutate("button mappings") { session, _ ->
            checkWrite(session.setButtonMappings(mappings))
            mappings
        }
    }

    fun setFindMode(enabled: Boolean) {
        mutate("find mode") { session, _ ->
            checkWrite(session.setFindMode(enabled))
            enabled
        }
    }

    fun close() {
        if (!closed.compareAndSet(false, true)) return
        foreground.set(false)
        generation.incrementAndGet()
        executor.execute {
            disconnectLocked()
            executor.shutdown()
        }
        listener.set(null)
    }

    @SuppressLint("MissingPermission")
    private fun connectAndRefreshLocked(gen: Int) {
        if (!foreground.get() || gen != generation.get()) return
        emitState(ConnectionState.Connecting)
        emitBusy(true)
        try {
            val adapter = bluetoothAdapter()
                ?: run {
                    emitState(
                        ConnectionState.Unavailable(
                            title = "Bluetooth unavailable",
                            message = "This device does not expose a Bluetooth adapter.",
                            canRetry = false,
                        ),
                    )
                    return
                }
            if (!adapter.isEnabled) {
                emitState(ConnectionState.BluetoothOff)
                return
            }

            val bonded = adapter.bondedDevices.orEmpty().toList()
            val device = bonded.firstOrNull { DeviceSupport.isTarget(it) }
            if (device == null) {
                emitState(ConnectionState.NotBonded)
                return
            }

            disconnectLocked()
            val connected = HeadsetSession.connect(
                adapter = adapter,
                device = device,
                trace = { Log.d(TAG, it) },
                onSocketCreated = { activeSocket = it },
                shouldCancel = { !foreground.get() || gen != generation.get() || closed.get() },
            )
            if (!foreground.get() || gen != generation.get()) {
                connected.close()
                return
            }
            session = connected
            val snapshot = readSnapshot(connected)
            lastSnapshot = snapshot
            emitState(ConnectionState.Connected(snapshot))
        } catch (error: Exception) {
            handleSessionFailure(error, gen)
        } finally {
            emitBusy(false)
        }
    }

    private fun mutate(label: String, block: (HeadsetSession, HeadsetSnapshot) -> Any?) {
        if (!foreground.get()) {
            emitMessage("Open Realme Unlink while the earbuds are nearby.", isError = true)
            return
        }
        val gen = generation.get()
        executor.execute {
            if (!foreground.get() || gen != generation.get()) return@execute
            emitBusy(true)
            try {
                var current = session
                if (current == null) {
                    connectAndRefreshLocked(gen)
                    current = session
                }
                val live = current ?: error("Not connected")
                val before = lastSnapshot ?: readSnapshot(live)
                block(live, before)
                val after = readSnapshot(live)
                lastSnapshot = after
                emitState(ConnectionState.Connected(after))
            } catch (error: Exception) {
                Log.w(TAG, "Failed $label", error)
                handleSessionFailure(error, gen, userLabel = label)
            } finally {
                emitBusy(false)
            }
        }
    }

    private fun handleSessionFailure(
        error: Exception,
        gen: Int,
        userLabel: String? = null,
    ) {
        disconnectLocked()
        if (!foreground.get() || gen != generation.get()) return
        val message = error.message.orEmpty()
        val title = when {
            message.contains("timed out", ignoreCase = true) -> "Earbuds not responding"
            message.contains("cancel", ignoreCase = true) -> "Connection cancelled"
            else -> "Couldn’t reach the earbuds"
        }
        val detail = buildString {
            append("Wake the earbuds and try again.")
            if (userLabel != null) {
                append(" ($userLabel)")
            }
        }
        emitState(
            ConnectionState.Unavailable(
                title = title,
                message = detail,
                canRetry = true,
            ),
        )
        if (userLabel != null) {
            emitMessage("Couldn’t update $userLabel", isError = true)
        }
    }

    private fun disconnectLocked() {
        try {
            session?.close()
        } catch (_: Exception) {
        }
        session = null
        try {
            activeSocket?.close()
        } catch (_: IOException) {
        }
        activeSocket = null
    }

    private fun readSnapshot(session: HeadsetSession): HeadsetSnapshot {
        val capabilityFrame = session.queryCapabilities()
        val capabilities = HeadsetCapabilities.parse(capabilityFrame)
            ?: error("Capability response was invalid")

        val batteries = if (capabilities.supportsCommand(HeadsetProtocol.BATTERY_COMMAND)) {
            runCatching {
                HeadsetProtocol.parseBatteries(session.queryBattery()).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val noise = if (capabilities.supportsCommand(HeadsetProtocol.NOISE_LEVEL_COMMAND)) {
            runCatching { HeadsetProtocol.parseNoiseControl(session.queryNoiseControl()) }
                .getOrNull()
        } else {
            null
        }

        val firmware = if (capabilities.supportsCommand(HeadsetProtocol.VERSION_COMMAND)) {
            runCatching {
                val frame = session.transact(HeadsetProtocol.VERSION_COMMAND)
                HeadsetCapabilityDiscovery.parseVersion(frame)
                    ?.firstOrNull { it.second == "2" || it.second == "3" }
                    ?.third
                    ?: HeadsetCapabilityDiscovery.parseVersion(frame)?.firstOrNull()?.third
            }.getOrNull()
        } else {
            null
        }

        val buttonMappings = if (capabilities.supportsCommand(HeadsetProtocol.KEY_FUNCTION_COMMAND)) {
            runCatching {
                val query = HeadsetCapabilityDiscovery.readOnlyQueries.first {
                    it.command == HeadsetProtocol.KEY_FUNCTION_COMMAND
                }
                HeadsetCapabilityDiscovery.parseKeyMappings(
                    session.transact(query.command, query.payload),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val wear = if (capabilities.supportsCommand(HeadsetProtocol.WEAR_STATUS_COMMAND)) {
            runCatching {
                HeadsetCapabilityDiscovery.parseWearStatus(
                    session.transact(HeadsetProtocol.WEAR_STATUS_COMMAND),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val switchStatuses = if (capabilities.supportsCommand(HeadsetProtocol.SWITCH_FEATURE_COMMAND)) {
            runCatching {
                val query = HeadsetCapabilityDiscovery.readOnlyQueries.first {
                    it.command == HeadsetProtocol.SWITCH_FEATURE_COMMAND
                }
                HeadsetCapabilityDiscovery.parseSwitchFeatureStatus(
                    session.transact(query.command, query.payload),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val currentEqId = if (capabilities.supportsCommand(HeadsetProtocol.EQ_STATUS_COMMAND)) {
            runCatching {
                HeadsetCapabilityDiscovery.parseEqStatus(
                    session.transact(HeadsetProtocol.EQ_STATUS_COMMAND),
                )
            }.getOrNull()
        } else {
            null
        }

        val eqProfiles = if (capabilities.supportsCommand(HeadsetProtocol.ALL_EQ_COMMAND)) {
            runCatching {
                HeadsetCapabilityDiscovery.parseEqProfiles(
                    session.transact(HeadsetProtocol.ALL_EQ_COMMAND),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val multipoint = if (capabilities.supportsCommand(HeadsetProtocol.MULTI_CONNECT_COMMAND)) {
            runCatching {
                HeadsetCapabilityDiscovery.parseMultipointStatus(
                    session.transact(HeadsetProtocol.MULTI_CONNECT_COMMAND),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        val bassBands = if (capabilities.supportsCommand(HeadsetProtocol.MULTI_BASS_ENGINE_COMMAND)) {
            runCatching {
                HeadsetCapabilityDiscovery.parseMultiBassEngine(
                    session.transact(HeadsetProtocol.MULTI_BASS_ENGINE_COMMAND),
                ).orEmpty()
            }.getOrDefault(emptyList())
        } else {
            emptyList()
        }

        return HeadsetSnapshot(
            deviceName = session.deviceName,
            serviceLabel = session.service,
            firmwareVersion = firmware,
            batteries = batteries.map {
                HeadsetSnapshot.BatteryLevel(it.deviceType, it.percentage, it.charging)
            },
            noise = noise,
            currentEqId = currentEqId,
            eqProfiles = eqProfiles,
            bassBands = bassBands,
            switches = SwitchCatalog.logicalSwitches(switchStatuses),
            buttonMappings = buttonMappings,
            wear = wear,
            multipoint = multipoint,
            findModeActive = lastSnapshot?.findModeActive == true,
            capabilities = capabilities,
        )
    }

    private fun checkWrite(frame: HeadsetProtocol.Frame) {
        val status = HeadsetProtocol.parseSetStatus(frame)
        check(status == 0) { "Headset rejected write (status=$status)" }
    }

    private fun bluetoothAdapter(): BluetoothAdapter? {
        val manager = appContext.getSystemService(BluetoothManager::class.java) ?: return null
        return manager.adapter
    }

    private fun emitState(state: ConnectionState) {
        listener.get()?.invoke(UiEvent.State(state))
    }

    private fun emitMessage(text: String, isError: Boolean) {
        listener.get()?.invoke(UiEvent.Message(text, isError))
    }

    private fun emitBusy(busy: Boolean) {
        listener.get()?.invoke(UiEvent.Busy(busy))
    }

    private companion object {
        const val TAG = "UnlinkController"
    }
}

