                Text("Allow multipoint", Modifier.weight(1f), style = MaterialTheme.typography.bodyLarge)
                Switch(
                    checked = sw.enabled,
                    onCheckedChange = { if (enabled) onToggle(sw.id, it) },
                    enabled = enabled,
                )
            }
        }
    }
}

