@Composable
private fun CustomEqSheet(
    snapshot: HeadsetSnapshot,
    onApply: (HeadsetCapabilityDiscovery.EqProfile) -> Unit,
    onClose: () -> Unit,
) {
    val base = snapshot.customEqProfile ?: return
    var bands by remember(base) { mutableStateOf(base.dbValues) }

    Column(
        Modifier
            .fillMaxWidth()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 20.dp)
            .padding(bottom = 32.dp),
    ) {
        Text("Custom EQ", style = MaterialTheme.typography.headlineSmall)
        Text(
            base.name.ifBlank { "Custom1" },
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Spacer(Modifier.height(16.dp))
        Text("Suggestions", style = MaterialTheme.typography.titleSmall)
        Spacer(Modifier.height(8.dp))
        FlowRow(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            EqSuggestions.suggestions.forEach { suggestion ->
                FilterChip(
                    selected = false,
                    onClick = {
                        bands = EqSuggestions.apply(base, suggestion).dbValues
                    },
                    label = { Text(suggestion.name) },
                )
            }
        }
        Spacer(Modifier.height(20.dp))
        base.frequencies.forEachIndexed { index, freq ->
            val value = bands.getOrElse(index) { 0 }
            var slider by remember(index, bands) { mutableFloatStateOf(value.toFloat()) }
            Text(
                formatFreq(freq) + " · ${slider.toInt()} dB",
                style = MaterialTheme.typography.labelLarge,
            )
            Slider(
                value = slider,
                onValueChange = {
                    slider = it
                    bands = bands.toMutableList().also { list ->
                        if (index < list.size) list[index] = it.toInt()
                    }
                },
                valueRange = base.minValue.toFloat()..base.maxValue.toFloat(),
                steps = (base.maxValue - base.minValue - 1).coerceAtLeast(0),
            )
        }
        Spacer(Modifier.height(12.dp))
        Button(
            onClick = {
                onApply(base.copy(dbValues = bands, selected = true))
            },
            modifier = Modifier.fillMaxWidth(),
        ) {
            Text("Apply to ${base.name.ifBlank { "Custom1" }}")
        }
        TextButton(onClick = onClose, modifier = Modifier.fillMaxWidth()) {
            Text("Cancel")
        }
    }
}

@Composable
private fun ButtonsSheet(
    mappings: List<HeadsetCapabilityDiscovery.KeyMapping>,
    onSave: (List<HeadsetCapabilityDiscovery.KeyMapping>) -> Unit,
    onClose: () -> Unit,
) {
    // Media functions validated for remap; keep volume functions selectable but honest.
    val functions = listOf(1, 2, 3, 4, 5, 6, 7, 8, 9, 0)
    var draft by remember(mappings) { mutableStateOf(mappings) }

    Column(
        Modifier
            .fillMaxWidth()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 20.dp)
            .padding(bottom = 32.dp),
    ) {
        Text("Gestures", style = MaterialTheme.typography.headlineSmall)
        Text(
            "Choose what each press does.",
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Spacer(Modifier.height(16.dp))
        draft.forEachIndexed { index, mapping ->
            Text(
                buildString {
                    append(HeadsetSemantics.wearRole(mapping.deviceType))
                    append(" · ")
                    append(HeadsetSemantics.buttonActionLabel(mapping.action))
                },
                style = MaterialTheme.typography.titleSmall,
            )
            Spacer(Modifier.height(6.dp))
            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                functions.forEach { function ->
                    FilterChip(
                        selected = mapping.function == function,
                        onClick = {
                            draft = draft.toMutableList().also {
                                it[index] = mapping.copy(function = function)
                            }
                        },
                        label = {
                            Text(HeadsetSemantics.buttonFunctionLabel(function))
                        },
                    )
                }
            }
            Spacer(Modifier.height(14.dp))
        }
        Button(
            onClick = { onSave(draft) },
            modifier = Modifier.fillMaxWidth(),
        ) {
            Text("Save gestures")
        }
        TextButton(onClick = onClose, modifier = Modifier.fillMaxWidth()) {
            Text("Cancel")
        }
    }
}

private fun summarizeButtons(mappings: List<HeadsetCapabilityDiscovery.KeyMapping>): String {
    return mappings.take(3).joinToString(" · ") {
        HeadsetSemantics.buttonActionLabel(it.action) + " → " +
            HeadsetSemantics.buttonFunctionLabel(it.function)
    } + if (mappings.size > 3) "…" else ""
}

private fun formatFreq(hz: Int): String = when {
    hz >= 1000 && hz % 1000 == 0 -> "${hz / 1000} kHz"
    hz >= 1000 -> String.format("%.1f kHz", hz / 1000f)
    else -> "$hz Hz"
}

package app.realme.unlink

import android.Manifest
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.util.Log
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.core.content.ContextCompat
import androidx.lifecycle.DefaultLifecycleObserver
import androidx.lifecycle.LifecycleOwner
import app.realme.unlink.ui.UnlinkApp
import app.realme.unlink.ui.UnlinkTheme
import java.util.concurrent.Executors

class MainActivity : ComponentActivity() {
    private lateinit var controller: HeadsetController

    private var connectionState by mutableStateOf<ConnectionState>(ConnectionState.Checking)
    private var busy by mutableStateOf(false)
    private var snackbarMessage by mutableStateOf<String?>(null)
    private var permissionGranted by mutableStateOf(false)

    private val permissionLauncher = registerForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) { result ->
        permissionGranted = result.values.all { it }
        if (permissionGranted) {
            controller.onForeground()
        } else {
            connectionState = ConnectionState.PermissionNeeded
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        controller = HeadsetController(applicationContext)
        controller.setListener { event ->
            runOnUiThread {
                when (event) {
                    is HeadsetController.UiEvent.State -> connectionState = event.state
                    is HeadsetController.UiEvent.Message -> snackbarMessage = event.text
                    is HeadsetController.UiEvent.Busy -> busy = event.busy
                }
            }
        }

        lifecycle.addObserver(object : DefaultLifecycleObserver {
            override fun onStart(owner: LifecycleOwner) {
                if (hasBluetoothPermission()) {
                    permissionGranted = true
                    controller.onForeground()
                } else {
                    connectionState = ConnectionState.PermissionNeeded
                }
            }

            override fun onStop(owner: LifecycleOwner) {
                controller.onBackground()
            }
        })

        setContent {
            UnlinkTheme {
                UnlinkApp(
                    state = connectionState,
                    busy = busy,
                    snackbarMessage = snackbarMessage,
                    onSnackbarConsumed = { snackbarMessage = null },
                    onRefresh = {
                        if (!hasBluetoothPermission()) {
                            requestBluetoothPermission()
                        } else {
                            controller.refresh()
                        }
                    },
                    onRequestPermission = { requestBluetoothPermission() },
                    onNoiseValue = controller::setNoiseValue,
                    onEqId = controller::setEqId,
                    onApplyCustomEq = controller::applyCustomEq,
                    onBassBand = controller::setBassBand,
                    onSwitch = controller::setSwitch,
                    onButtons = controller::setButtonMappings,
                    onFindMode = controller::setFindMode,
                )
            }
        }

        // Diagnostics remain code-only; never surfaced in UI. Debug builds may still run the
        // evidence matrix via intent extra for automation.
        if (BuildConfig.ENABLE_DIAGNOSTICS &&
            intent?.getBooleanExtra(EXTRA_RUN_EVIDENCE_MATRIX, false) == true
        ) {
            runEvidenceMatrixAutomation()
        }
    }

    override fun onDestroy() {
        controller.close()
        super.onDestroy()
    }

    private fun hasBluetoothPermission(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) return true
        return REQUIRED_PERMISSIONS.all {
            ContextCompat.checkSelfPermission(this, it) == PackageManager.PERMISSION_GRANTED
        }
    }

    private fun requestBluetoothPermission() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) {
            permissionGranted = true
            controller.onForeground()
            return
        }
        permissionLauncher.launch(REQUIRED_PERMISSIONS)
    }

    private fun runEvidenceMatrixAutomation() {
        if (!hasBluetoothPermission()) {
            requestBluetoothPermission()
            return
        }
        val executor = Executors.newSingleThreadExecutor()
        executor.execute {
            try {
                val probe = HeadsetEvidenceProbe(applicationContext)
                val result = probe.run()
                Log.i(EVIDENCE_TAG, "Evidence matrix finished: ${result.summary}")
                result.findings.forEach { Log.i(EVIDENCE_TAG, "FINDING: $it") }
            } catch (error: Exception) {
                Log.e(EVIDENCE_TAG, "Evidence matrix failed", error)
            } finally {
                executor.shutdown()
            }
        }
    }

    companion object {
        const val EXTRA_RUN_EVIDENCE_MATRIX = "run_evidence_matrix"
        private const val EVIDENCE_TAG = "UnlinkEvidence"
        private val REQUIRED_PERMISSIONS = arrayOf(
            Manifest.permission.BLUETOOTH_CONNECT,
            Manifest.permission.BLUETOOTH_SCAN,
        )
    }
}

